{"path":"analyze.py","content":"from PIL import Image
import numpy as np, colorsys, os

im = Image.open('barcode.png').convert('RGB')
W, H = im.size
a = np.asarray(im).astype(int)          # H x W x 3
colmean = a.mean(axis=0)                # W x 3 (average color of each column)

# Stripe boundaries: a clean barcode PNG has flat columns; detect any column change
diff = np.abs(np.diff(colmean, axis=0)).max(axis=1)     # length W-1
bounds = [0] + [i + 1 for i in range(len(diff)) if diff[i] > 0] + [W]
print(f'size: {W}x{H}, raw change points: {len(bounds)-2}')

ranges = list(zip(bounds[:-1], bounds[1:]))
stripes = [(s, e, colmean[s:e].mean(axis=0)) for s, e in ranges]

# merge adjacent columns that are essentially the same color
merged = []
for s, e, c in stripes:
    if merged and np.abs(merged[-1][2] - c).max() < 3:
        ps, pe, pc = merged[-1]
        merged[-1] = (ps, e, (pc * (pe - ps) + c * (e - s)) / (pe - ps))
    else:
        merged.append((s, e, c))
print(f'num stripes (merged): {len(merged)}')

def hx(c):
    return '#%02x%02x%02x' % tuple(int(round(x)) for x in c)

def hue_of(c):
    r, g, b = [x / 255.0 for x in c]
    h, s, v = colorsys.rgb_to_hsv(r, g, b)
    return h * 360, s, v

print('\n--- stripe colors ---')
for i, (s, e, c) in enumerate(merged):
    h, s2, v = hue_of(c)
    print(f'{i:3d} x={s:4d}-{e:4d} w={e-s:3d} {hx(c)} hue={h:5.1f} sat={s2:4.2f} val={v:4.2f}')

print('\n--- 24 chunk averages ---')
for k in range(24):
    s, e = W * k // 24, W * (k + 1) // 24
    c = colmean[s:e].mean(axis=0)
    h, s2, v = hue_of(c)
    print(f'chunk {k:2d} (x {s:4d}-{e:4d}) {hx(c)} hue={h:5.1f} sat={s2:4.2f} val={v:4.2f}')

print('\n--- hue buckets over stripes ---')
buckets = {'achromatic(sat<.08)': 0, 'red': 0, 'orange': 0, 'yellow': 0,
           'green': 0, 'cyan': 0, 'blue': 0, 'purple/magenta': 0}
for s, e, c in merged:
    h, s2, v = hue_of(c)
    if s2 < 0.08:
        buckets['achromatic(sat<.08)'] += 1
    elif h < 20 or h >= 340:
        buckets['red'] += 1
    elif h < 45:
        buckets['orange'] += 1
    elif h < 70:
        buckets['yellow'] += 1
    elif h < 160:
        buckets['green'] += 1
    elif h < 200:
        buckets['cyan'] += 1
    elif h < 260:
        buckets['blue'] += 1
    else:
        buckets['purple/magenta'] += 1
for k, v in buckets.items():
    print(f'{k:22s} {v}')

# save enlarged versions for visual inspection
im.resize((W * 3, H * 3), Image.NEAREST).save('barcode_big.png')
im.crop((0, 0, W // 2, H)).resize((W // 2 * 3, H * 3), Image.NEAREST).save('left.png')
im.crop((W // 2, 0, W, H)).resize((W // 2 * 3, H * 3), Image.NEAREST).save('right.png')
print('\nsaved barcode_big.png, left.png, right.png')"}

